<?php
namespace App\Controllers;
use App\Services\CashService;
use App\Services\PermissionService;
use CodeIgniter\Controller;
class Cash extends Controller {
 private function guard(): ?\CodeIgniter\HTTP\ResponseInterface { if(!PermissionService::allows('CASH_MANAGE')) return $this->response->setStatusCode(403)->setBody('Forbidden'); return null; }
 public function index(){if($r=$this->guard())return $r;$s=new CashService();$session=$s->openSessionForLocation((int)session()->get('location_id'));return view('cash/index',['title'=>'Counter Cash','session'=>$session,'summary'=>$session?$s->summary((int)$session['id']):null]);}
 public function open(){if($r=$this->guard())return $r;try{(new CashService())->openSession((int)session()->get('user_id'),(int)session()->get('location_id'),(float)$this->request->getPost('opening_cash'),(string)$this->request->getPost('notes'));return redirect()->to('/cash')->with('success','Cash session opened.');}catch(\Throwable $e){return redirect()->back()->withInput()->with('error',$e->getMessage());}}
 public function move(){if($r=$this->guard())return $r;try{$s=(new CashService())->openSessionForLocation((int)session()->get('location_id'));if(!$s)throw new \RuntimeException('Open a cash session first.');$amount=(float)$this->request->getPost('amount');$direction=(string)$this->request->getPost('direction');$type=$direction==='in'?'manual_in':'manual_out';(new CashService())->postGeneric((int)$s['id'],$type,$direction,$amount,'cash_manual',0,(int)session()->get('user_id'),(string)$this->request->getPost('notes'));return redirect()->to('/cash')->with('success','Cash movement posted.');}catch(\Throwable $e){return redirect()->back()->withInput()->with('error',$e->getMessage());}}
 public function history(){if($r=$this->guard())return $r;$from=$this->request->getGet('from');$to=$this->request->getGet('to');$registerId=$this->request->getGet('register_id');$s=new CashService();$rows=$s->history((int)session()->get('location_id'),$from?:null,$to?:null,$registerId?:(null));$registers=\Config\Database::connect()->table('cash_registers')->where('location_id',(int)session()->get('location_id'))->where('is_active',1)->orderBy('code')->get()->getResultArray(); return view('cash/history',['title'=>'Counter Cash History','rows'=>$rows,'from'=>$from?:date('Y-m-d',strtotime('-30 days')),'to'=>$to?:date('Y-m-d'),'registerId'=>$registerId,'registers'=>$registers]);}
 public function close(){if($r=$this->guard())return $r;try{$x=(new CashService())->closeSession((int)$this->request->getPost('session_id'),(int)session()->get('user_id'),(float)$this->request->getPost('counted_cash'),(string)$this->request->getPost('notes'));return redirect()->to('/cash')->with('success','Cash session closed. Difference: Rs. '.number_format($x['difference'],2));}catch(\Throwable $e){return redirect()->back()->withInput()->with('error',$e->getMessage());}}
}